#include <random>
#include <iostream>

int main() {
    std::default_random_engine generator;  // URNG with internal state (e.g., 624 32-bit integers for std::mt19937)
    std::uniform_int_distribution<int> distribution(1, 6);  // Distribution with param_type holding min and max
    int random_number = distribution(generator);  // Invokes operator()(generator, distribution.param())
    std::cout << random_number << std::endl;  // Outputs a random integer between 1 and 6
    return 0;
}
